291	/// 对象标识符（OID），以各段弧的数值保存，用于向调用方展示实际标识。
292	#[derive(Debug, Clone, PartialEq, Eq, Hash)]
293	pub struct ObjectIdentifier(Vec<u64>);
294	
295	impl ObjectIdentifier {
296	    /// 返回各段弧的数值，例如 Ed25519 为 `[1, 3, 101, 112]`。
297	    pub fn arcs(&self) -> &[u64] {
298	        &self.0
299	    }
300	}
301	
302	impl fmt::Display for ObjectIdentifier {
303	    /// 点分十进制写法，例如 `1.3.101.112`。
304	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
305	        let mut arcs = self.0.iter();
306	        if let Some(first) = arcs.next() {
307	            write!(f, "{first}")?;
308	            for arc in arcs {
309	                write!(f, ".{arc}")?;
310	            }
311	        }
312	        Ok(())
313	    }
314	}
