316	/// 导入 Ed25519 公钥失败时返回的类型化错误。
317	///
318	/// 调用方按变体即可区分两类失败，无需分析提示字符串：编码或公钥结构
319	/// 不合法是 [`Malformed`](Self::Malformed)；结构完整、DER 合法但算法
320	/// 标识不是 Ed25519 是 [`UnsupportedAlgorithm`](Self::UnsupportedAlgorithm)。
321	/// 任何失败都不会产出可继续使用的公钥对象。
322	#[derive(Debug, Clone, PartialEq, Eq)]
323	pub enum ImportPublicKeyError {
324	    /// 输入不是一份完整、规范的 DER 编码 SubjectPublicKeyInfo：截断、
325	    /// 声明长度与实际内容不符、非规范长度编码、算法参数未缺省（含写成
326	    /// NULL）、位串未使用位数非零、公钥长度不是 32 字节、容器中出现
327	    /// 多余字段或对象之后还有字节等。
328	    Malformed,
329	    /// 整体编码合法，但算法标识不是 Ed25519（`1.3.101.112`）；携带实际
330	    /// 标识供调用方展示。
331	    UnsupportedAlgorithm(ObjectIdentifier),
332	}
333	
334	impl fmt::Display for ImportPublicKeyError {
335	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
336	        match self {
337	            ImportPublicKeyError::Malformed => write!(
338	                f,
339	                "input is not a well-formed DER-encoded Ed25519 SubjectPublicKeyInfo"
340	            ),
341	            ImportPublicKeyError::UnsupportedAlgorithm(oid) => write!(
342	                f,
343	                "unsupported public key algorithm {oid} (expected Ed25519, 1.3.101.112)"
344	            ),
345	        }
346	    }
347	}
348	
349	impl Error for ImportPublicKeyError {}
350	
351	const TAG_SEQUENCE: u8 = 0x30;
352	const TAG_OID: u8 = 0x06;
353	const TAG_BIT_STRING: u8 = 0x03;
354	
355	/// 读取一个 DER TLV，返回（标签，内容，剩余字节）。
356	///
357	/// 只接受规范（最短）定长编码：拒绝不定长形式、长形式的前导零字节，
358	/// 以及本可以用短形式表示的长度；声明长度超出实际剩余内容同样失败。
359	/// 本模块只使用单字节通用标签，多字节标签形式一律拒绝。
360	fn read_der_tlv(data: &[u8]) -> Option<(u8, &[u8], &[u8])> {
361	    let (&tag, rest) = data.split_first()?;
362	    if tag & 0x1f == 0x1f {
363	        return None;
364	    }
365	    let (&first_len, rest) = rest.split_first()?;
366	    let (len, rest) = if first_len & 0x80 == 0 {
367	        (first_len as usize, rest)
368	    } else {
369	        let n = (first_len & 0x7f) as usize;
370	        // 0x80 是不定长形式，DER 不允许；长度本身也不允许超过 8 字节。
371	        if n == 0 || n > 8 || rest.len() < n {
372	            return None;
373	        }
374	        let (len_bytes, rest) = rest.split_at(n);
375	        // 前导零字节是非规范编码。
376	        if len_bytes[0] == 0 {
377	            return None;
378	        }
379	        let mut value: u64 = 0;
380	        for &b in len_bytes {
381	            value = (value << 8) | u64::from(b);
382	        }
383	        // 能用短形式表示的长度却用了长形式，同样是非规范编码。
384	        if value < 128 {
385	            return None;
386	        }
387	        (usize::try_from(value).ok()?, rest)
388	    };
389	    if rest.len() < len {
390	        return None;
391	    }
392	    let (content, rest) = rest.split_at(len);
393	    Some((tag, content, rest))
394	}
395	
396	/// 把 OID 的 DER 内容字节解码为各段弧的数值。
397	///
398	/// 只接受规范编码：内容非空，每个子标识符按最短形式编码（不允许
399	/// 前导的 0x80 字节），最后一个子标识符必须完整结束，弧的数值
400	/// 不得溢出。
401	fn decode_oid(content: &[u8]) -> Option<ObjectIdentifier> {
402	    if content.is_empty() {
403	        return None;
404	    }
405	    let mut subidentifiers: Vec<u64> = Vec::new();
406	    let mut value: u64 = 0;
407	    let mut in_arc = false;
408	    for &b in content {
409	        if !in_arc {
410	            // 子标识符首字节为 0x80 是前导零的非规范编码。
411	            if b == 0x80 {
412	                return None;
413	            }
414	            in_arc = true;
415	        }
416	        if value > (u64::MAX >> 7) {
417	            return None;
418	        }
419	        value = (value << 7) | u64::from(b & 0x7f);
420	        if b & 0x80 == 0 {
421	            subidentifiers.push(value);
422	            value = 0;
423	            in_arc = false;
424	        }
425	    }
426	    // 最后一个子标识符的续位未结束：内容被截断。
427	    if in_arc {
428	        return None;
429	    }
430	    let (&first, rest) = subidentifiers.split_first()?;
431	    // 第一个子标识符合并编码前两段弧：0..=39 → 0.x，40..=79 → 1.x，
432	    // 其余 → 2.x。
433	    let (arc0, arc1) = if first < 40 {
434	        (0, first)
435	    } else if first < 80 {
436	        (1, first - 40)
437	    } else {
438	        (2, first - 80)
439	    };
440	    let mut arcs = Vec::with_capacity(rest.len() + 2);
441	    arcs.push(arc0);
442	    arcs.push(arc1);
443	    arcs.extend_from_slice(rest);
444	    Some(ObjectIdentifier(arcs))
445	}
