495	    /// 按给定片段长度序列依次返回输入字节的读取器；序列为空时每次读满。
496	    /// 用于模拟不同分块方式，验证摘要只取决于字节内容而非读取方式。
497	    struct ChunkedReader<'a> {
498	        data: &'a [u8],
499	        pos: usize,
500	        chunk_sizes: &'a [usize],
501	        chunk_index: usize,
502	    }
503	
504	    impl<'a> ChunkedReader<'a> {
505	        fn new(data: &'a [u8], chunk_sizes: &'a [usize]) -> Self {
506	            ChunkedReader { data, pos: 0, chunk_sizes, chunk_index: 0 }
507	        }
508	    }
509	
510	    impl Read for ChunkedReader<'_> {
511	        fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
512	            if self.pos == self.data.len() {
513	                return Ok(0);
514	            }
515	            let mut limit = buf.len();
516	            if !self.chunk_sizes.is_empty() {
517	                limit = limit.min(self.chunk_sizes[self.chunk_index % self.chunk_sizes.len()]);
518	                self.chunk_index += 1;
519	            }
520	            let n = limit.min(self.data.len() - self.pos);
521	            buf[..n].copy_from_slice(&self.data[self.pos..self.pos + n]);
522	            self.pos += n;
523	            Ok(n)
524	        }
525	    }
