578	    /// 按脚本驱动的读取器：每个步骤要么返回下一段内容（长度可短于缓冲区），
579	    /// 要么返回一个错误。脚本用完后继续返回剩余内容，内容耗尽后返回 Ok(0)。
580	    /// 用于精确模拟“中断出现在任意位置”的读取序列。
581	    enum Step {
582	        /// 返回下一段内容（可为空切片以外的任意长度）。
583	        Data,
584	        /// 返回指定错误。
585	        Fail(io::ErrorKind, &'static str),
586	    }
587	
588	    struct ScriptedReader<'a> {
589	        data: &'a [u8],
590	        pos: usize,
591	        steps: &'a [Step],
592	        step_index: usize,
593	    }
594	
595	    impl<'a> ScriptedReader<'a> {
596	        fn new(data: &'a [u8], steps: &'a [Step]) -> Self {
597	            ScriptedReader { data, pos: 0, steps, step_index: 0 }
598	        }
599	    }
600	
601	    impl Read for ScriptedReader<'_> {
602	        fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
603	            match self.steps.get(self.step_index) {
604	                Some(Step::Data) => {
605	                    self.step_index += 1;
606	                    // 每段最多给剩余内容的一半，保证一段脚本可能对应多次内容返回，
607	                    // 且片段长度通常短于缓冲区容量。
608	                    let remaining = self.data.len() - self.pos;
609	                    let n = (remaining / 2).max(1).min(remaining).min(buf.len());
610	                    buf[..n].copy_from_slice(&self.data[self.pos..self.pos + n]);
611	                    self.pos += n;
612	                    Ok(n)
613	                }
614	                Some(Step::Fail(kind, msg)) => {
615	                    self.step_index += 1;
616	                    Err(io::Error::new(*kind, *msg))
617	                }
618	                None => {
619	                    let remaining = self.data.len() - self.pos;
620	                    let n = remaining.min(buf.len());
621	                    buf[..n].copy_from_slice(&self.data[self.pos..self.pos + n]);
622	                    self.pos += n;
623	                    Ok(n)
624	                }
625	            }
626	        }
627	    }
