975	    /// 由算法 OID 内容字节与 32 字节公钥拼装一份规范编码的 SPKI。
976	    fn spki_der(oid_content: &[u8], key: &[u8; 32]) -> Vec<u8> {
977	        // 外层内容 = 算法序列（2 字节头 + 2 字节 OID 头 + OID 内容）
978	        //          + 位串（2 字节头 + 1 字节未使用位数 + 32 字节公钥）。
979	        let outer_len = oid_content.len() + 4 + 35;
980	        let mut der = vec![0x30, outer_len as u8, 0x30, (oid_content.len() + 2) as u8, 0x06];
981	        der.push(oid_content.len() as u8);
982	        der.extend_from_slice(oid_content);
983	        der.extend_from_slice(&[0x03, 0x21, 0x00]);
984	        der.extend_from_slice(key);
985	        der
986	    }
