646	/// 摘要文件格式错误的完整约定：退出码 2、标准输出为空，标准错误首先指出
647	/// 摘要文件（而非待核对文件）及其格式问题并给出用法；此时即使待核对文件
648	/// 不存在，也不能改报它的访问错误。
649	fn assert_malformed_digest_file(
650	    output: &Output,
651	    digest_name: &str,
652	    target_name: &str,
653	) -> String {
654	    assert_eq!(output.status.code(), Some(2), "exit code: {output:?}");
655	    assert!(
656	        output.stdout.is_empty(),
657	        "stdout must be empty on malformed digest file: {:?}",
658	        String::from_utf8_lossy(&output.stdout)
659	    );
660	    let stderr = String::from_utf8(output.stderr.clone()).expect("stderr must be UTF-8");
661	    assert!(
662	        stderr.starts_with("inkseal: malformed digest file '"),
663	        "must report the digest file as malformed: {stderr:?}"
664	    );
665	    assert!(
666	        stderr.contains(digest_name),
667	        "error must name the digest file {digest_name:?}: {stderr:?}"
668	    );
669	    assert!(
670	        stderr.contains("Usage:"),
671	        "usage for the new command must be shown: {stderr:?}"
672	    );
673	    assert!(
674	        stderr.contains("check-digest-file <file> <digest-file>"),
675	        "usage must include the new command: {stderr:?}"
676	    );
677	    // 摘要文件格式问题先于待核对文件处理：不得报告待核对文件的访问问题，
678	    // 提示里也不应出现待核对文件的名字。
679	    assert!(
680	        !stderr.contains("cannot open") && !stderr.contains("cannot read"),
681	        "digest file must be validated before touching the target (case {digest_name:?}): {stderr:?}"
682	    );
683	    assert!(
684	        !stderr.contains(target_name),
685	        "target must not be accessed or named (case {digest_name:?}): {stderr:?}"
686	    );
687	    stderr
688	}
